{
  "findings": [
    {
      "ref": "[D531]",
      "area": "contact",
      "claim": "A parent reports that strangers can message or voice chat with their child in Roblox, and this feature is on by default.",
      "stance": "risk",
      "quote": "On TikTok, parents must create a parent account, navigate multiple menus to a feature called Family Pairing, send a link to the teen, wait for them to accept within 48 hours and then toggle all the settings they want to control."
    },
    {
      "ref": "[D531]",
      "area": "money",
      "claim": "A parent reports that Roblox allows in-app purchases without parental consent, and the app pushes spending through loot boxes and pay-to-win mechanics.",
      "stance": "risk",
      "quote": "One example in 2022 involved over $16,000 in unauthorized in-app spending."
    },
    {
      "ref": "[D531]",
      "area": "data",
      "claim": "A parent reports that Roblox collects personal data from children under 13 without parental consent, and this data may be shared with third parties for advertising.",
      "stance": "risk",
      "quote": "Apple is also accused of knowingly allowing developers to collect personal data from children under 13 without parental consent, despite having actual knowledge of the user’s age."
    },
    {
      "ref": "[D531]",
      "area": "age_gating",
      "claim": "A parent reports that Roblox’s age gate can be bypassed by entering any birthdate before September 2007, making it ineffective in practice.",
      "stance": "risk",
      "quote": "A kid who wants to dodge all of the above can simply enter any birthdate before September 2007."
    },
    {
      "ref": "[D531]",
      "area": "content",
      "claim": "A parent reports that Roblox contains inappropriate or harmful content that is marketed as safe for kids.",
      "stance": "risk",
      "quote": "First, the complaint alleges that Apple’s app rating process is inadequate and deceptive, relying on developers’ self-reported answers without fully assessing harmful content."
    },
    {
      "ref": "[D531]",
      "area": "developer_record",
      "claim": "A parent reports that Roblox’s developer has faced regulatory actions for violating children’s privacy and in-app purchase rules.",
      "stance": "risk",
      "quote": "In 2019, ByteDance’s TikTok paid a $5.7 million penalty for unlawfully collecting data from children under 13; YouTube settled for $170 million for knowingly collecting personal information from children through “made for kids” content; and in 2023, Microsoft was fined $20 million for allowing children under 13 to create Xbox accounts without proper parental consent."
    }
  ]
}
